package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log, oldest first: a line per status it has had,
 *  {@code <STATUS> by <user> on <sheet's today> due=<due as computed then, n/a when no rate applied>}. */
@Repository
public class ClaimLogStore {

    private final JdbcTemplate jdbc;
    private final ClaimStore claims;
    private final PersonStore people;
    private final RateStore rates;
    private final SettingStore settings;
    private final SheetStore sheets;

    public ClaimLogStore(JdbcTemplate jdbc, ClaimStore claims, PersonStore people, RateStore rates,
            SettingStore settings, SheetStore sheets) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Logs the claim's current status, by the user, on the sheet's today, at its due as the screen
     *  works it out now (its settled due once settled, else its figure plus any late charge). */
    public void record(Claim claim, String user) {
        String sheetId = claim.getSheetId();
        LocalDate today = sheets.today(sheetId);
        Person person = people.find(sheetId, claim.getPersonId());
        BigDecimal pct = person == null ? null
                : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(sheetId, settings, sheets, claims).due(claim, pct);
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, claim.getId(), claim.getStatus().name(), user, Date.valueOf(today),
                due == null ? "n/a" : due.setScale(2).toPlainString());
    }

    /** Every claim's log lines on the sheet, by claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            lines.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getObject("log_date", LocalDate.class) + " due=" + rs.getString("due"));
        }, sheetId);
        return lines;
    }

    /** Each claim's status at the end of the date, by claim id, as its log records it: the last status
     *  logged on or before the date. A claim logged only after it (added after it) is absent. */
    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate date) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND log_date <= ? ORDER BY id", rs -> {
            statuses.put(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")));
        }, sheetId, Date.valueOf(date));
        return statuses;
    }

    /** The claim's log lines, oldest first. */
    public List<String> lines(Claim claim) {
        return lines(claim.getSheetId()).getOrDefault(claim.getId(), List.of());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.watch.Notify;
import net.officefloor.hq.app.watch.WatchStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored status change: CLAIM_OPENED, CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED,
 *  CLAIM_REJECTED or CLAIM_VOIDED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>,
 *  then number=<n> when the claim has or had a number, then for CLAIM_SETTLED and CLAIM_APPROVED
 *  due=<0.00> as fixed on settling (n/a when its grade had no rate), for CLAIM_REJECTED reason=<reason>.
 *  A claim settled or approved then tells the person's watchers (NOTIFY), before the figures moved. */
public class AuditClaimStatus {
    public void audit(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, @Val StatusChange change, @Val Rollup before,
            PersonStore people, Audit audit, RollupService rollups, WatchStore watches) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record(move.to().event(move.from()) + " sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (change.number() == null ? "" : " number=" + change.number())
                + (move.to() == ClaimStatus.SETTLED ? " due=" + (shown.due() == null ? "n/a" : shown.due()) : "")
                + (move.from() == ClaimStatus.PENDING && move.to() == ClaimStatus.OPEN ? " reason=" + input.reason() : ""));
        if (move.to() == ClaimStatus.SETTLED) {
            Notify.watchers(watches, audit, person, input.user(), change.number());
        }
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a change to a claim dated inside a closed period: editing it or moving it on. */
public class CheckClaimPeriod {
    public void check(@Val Claim claim, PeriodStore periods) throws InvalidSheetException {
        refuseClosed(periods, claim.getSheetId(), claim.getDate());
    }

    static void refuseClosed(PeriodStore periods, String sheetId, LocalDate date) throws InvalidSheetException {
        PeriodResponse closed = periods.closedOn(sheetId, date);
        if (closed != null) {
            throw new InvalidSheetException("The period " + closed.name() + " is closed");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateStatus {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody StatusRequest request, Out<StatusInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String status = request == null || request.status() == null ? "" : request.status().trim();
        ClaimStatus to;
        try {
            to = ClaimStatus.valueOf(status);
        } catch (IllegalArgumentException e) {
            throw new InvalidSheetException("Not a claim status: " + status);
        }
        boolean review = Boolean.TRUE.equals(request.review());
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (review && to != ClaimStatus.SETTLED && to != ClaimStatus.OPEN) {
            throw new InvalidSheetException("A review approves or rejects a claim");
        }
        if (review && to == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new InvalidSheetException("A rejection needs a reason");
        }
        body.set(new StatusInput(to, request.user(), review, reason));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Works out the move a status change makes. A clerk settling an OPEN claim whose due is above the
 *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
 *  sheet with no limit, and a steward, settle anything. Only a steward reviews a PENDING claim, and
 *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused.
 *  Before the limit is considered, settling or approving a claim with no proofs whose due is above the
 *  proof threshold is refused (see {@link CheckProofs}), so it never goes to PENDING. Opening, settling
 *  and voiding are refused to a role the sheet's permission matrix does not allow it. */
public class CheckClerkLimit {
    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, Out<StatusMove> move)
            throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        Role role = roles.find(claim.getSheetId(), input.user());
        boolean steward = role == Role.STEWARD;
        if (input.review()) {
            if (from != ClaimStatus.PENDING) {
                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
            }
            if (!steward) {
                throw new InvalidSheetException("Only a steward can approve or reject a claim");
            }
            CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
            move.set(new StatusMove(from, input.status()));
            return;
        }
        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
        }
        refuseUnpermitted(input.status(), claim.getSheetId(), role, settings);
